import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Video Generation Models are General-Purpose Vision Learners","description":"","frontmatter":{"title":"Video Generation Models are General-Purpose Vision Learners","arxiv":"2607.09024","date":"2026-07-10","authors":"Letian Wang, Chuhan Zhang, Rishabh Kabra, Jasper Uijlings, Steven Waslander, Andrew Zisserman, Joao Carreira, Kaiming He, Misha Andriluka, Eduard Gabriel Bazavan, Andrei Zanfir, Cristian Sminchisescu","categories":"cs.CV, cs.AI","topics":"物理感知视频生成, 生成式预训练, 通用视觉模型","outline":[2,2]},"headers":[],"relativePath":"papers/2607.09024.md","filePath":"papers/2607.09024.md","lastUpdated":null}'),e={name:"papers/2607.09024.md"};function l(i,s,r,m,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="video-generation-models-are-general-purpose-vision-learners" tabindex="-1">Video Generation Models are General-Purpose Vision Learners <a class="header-anchor" href="#video-generation-models-are-general-purpose-vision-learners" aria-label="Permalink to &quot;Video Generation Models are General-Purpose Vision Learners&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.09024" target="_blank" rel="noreferrer">2607.09024</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-10</td></tr><tr><td><strong>作者</strong></td><td>Letian Wang, Chuhan Zhang, Rishabh Kabra, Jasper Uijlings, Steven Waslander, Andrew Zisserman, Joao Carreira, Kaiming He, Misha Andriluka, Eduard Gabriel Bazavan, Andrei Zanfir, Cristian Sminchisescu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把文生视频扩散模型当作视觉预训练基座：固定时间步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>、对速度输出取负，改成单步前向；稠密任务统一编码进 3 通道 RGB，稀疏任务交给可学习 token，全部用一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 损失、靠文本指令切换任务。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文为 arXiv v1（2026-07-10），ECCV 2026 接收。方法名 GenCeption，项目页 genception.github.io。作者为 Google DeepMind 团队。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>NLP 靠 next-token prediction 一个目标把翻译、摘要、问答收进同一个基座模型；视觉至今没有对应的东西。Segment Anything 系列和 Depth Anything 系列确实很强，但它们仍是每个任务一套架构、一套 decoder、一套损失。这篇论文问的是：视觉的「next-token prediction」是什么。</p><p>作者的回答是大规模文生视频生成。理由是它同时满足三条：视频生成必须内化 4D 时空演化（几何、物体恒存性、物理交互）；文生视频天然带文本条件，所以视觉特征原生和语言对齐；这类模型因为标注成本低、商业价值高，已经被推到了很大的数据与算力规模。这三条恰好是 contrastive learning 和 masked autoencoder 各缺一条的。</p><p>价值不只是「多一个 backbone」。如果成立，任务规格就从「改架构」变成「改数据表示」，新增视觉能力不再需要动模型；这正是 LLM 时代的工程范式。对具身与物理感知方向，它还给出一个更强的说法：生成模型内部那个被反复猜测的「world model」，可以被直接读出来当感知器用。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>重新利用扩散模型做感知已经有一条清晰的脉络。Marigold 把 Stable Diffusion 微调成单目深度估计器；后续工作把时间步与噪声水平对齐，做出单步确定性模型；GenPercept 系统梳理了特征注入、解码机制与训练目标；Diception 用文本提示在图像域上驱动多任务。这些方法的共同短板是单图输入，套到视频序列上时序不一致。</p><p>于是又有一批工作转向原生视频扩散：BufferAnytime 给图像扩散加时序层，DepthCrafter 和 NormalCrafter 引入 CLIP/DINO 对齐目标辅助训练，Geo4D 做 4D 重建，ReferEverything 把视频扩散改造成指代分割。问题在于它们几乎都只攻一个稠密任务，而且大多保留了多步采样，推理慢。</p><p>统一模型这条线（4M、David 等）主要在图像域，且多任务往往靠 task-specific encoder/decoder/loss 硬拼，架构层面并不统一。本文明确点名两个并发工作：Wiedemer 等人验证了视频生成模型确实携带可复用的视觉先验，但走的是 training-free 多步生成加定性验证；Vision Banana 在 2D 图像空间操作。作者的定位是「他们证明先验存在，我们给出高效榨取先验的架构」。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在这篇论文之前，已经存在的线索有三条。第一，Marigold 一类工作证明扩散骨干里确实藏着可用的几何信息，且用少量合成数据微调就能取出来。第二，Rectified Flow 的训练目标是回归速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，这意味着模型在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 附近本质上在做一件和「从干净输入抽特征」很接近的事。第三，多步采样对生成有意义（要采样多样性），对感知却是纯粹的浪费——感知要的是准确、确定、快。</p><p>把这三条拼起来就得到一个很自然的想法：既然要的是特征而不是采样，那就干脆把干净 latent 直接喂进 DiT，把时间步钉死在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>，只跑一次前向。剩下的问题是多任务怎么统一。这里的关键取舍是「改架构」还是「改数据」。前者已经被证明会破坏预训练特征、需要更多数据才能收敛；后者在 LLM 里已经被验证过（把非文本数据格式化成文本串）。于是作者选择把所有稠密任务都投影回 3 通道 RGB 空间——这是预训练先验最擅长的原生域。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视频扩散模型为了生成一段可信的视频，必须先在内部把深度、法线、物体边界、相机运动都算清楚；这些量已经在网络里了，只是被生成头包装成了像素。与其重新训练一个感知器，不如把生成流程反过来用：喂干净 latent、固定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>、把速度预测取负，模型最后一层输出的就是最接近目标视频 latent 的东西。任务不同只是目标视频的「颜色约定」不同——深度是灰度图、法线是三通道向量图、相机位姿是拼成 RGB 的射线图——所以一个 backbone、一个 decoder、一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 损失就够了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「给一段滑雪视频估计 3D 人体关键点和深度」为例：</p><ol><li><strong>输入</strong>：RGB 视频（480×832、81 帧、24 FPS）经 VAE 编码为干净 latent（时间下采样 4×、空间 8×），文本提示指定目标模态。</li><li><strong>单步前向</strong>：不加噪、条件时间步固定为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>，DiT 只跑一次。由于骨干是 Rectified Flow 训练的，作者对原始输出取负号再送入损失/解码器。</li><li><strong>稠密任务</strong>：深度、法线、前景分割、指代分割、DensePose、raymap 全部输出到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 的 3 通道 RGB。单通道量（深度、mask）复制三份；相机位姿用「Rothko」射线图——6 通道的射线原点与方向被空间切分，原点放中央、方向放四周，硬塞进 3 通道。</li><li><strong>稀疏任务</strong>：给每一帧追加一个可学习 token（共 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 个）拼到视频 latent 后面，过完 DiT 后用 MLP 解码出每帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 维坐标。这些 token 的空间位置未知所以设为可学习，时间位置用 position interpolation 压到预训练见过的范围内。</li><li><strong>数据</strong>：800 个 RenderPeople 资产 × 200 段 CMU 动捕，配 3D 场景/HDRI 背景与随机焦距相机，Blender 分 pass 渲染出 7,500 段合成视频的深度/法线/mask；关键点真值直接取自绑定骨骼。再补 TartanAir、Virtual KITTI、MVS Synth；只有指代分割用了真实数据（MeViS、RefCOCO、YouTube-VOS）。</li><li><strong>训练</strong>：batch 64、256 颗 v6e TPU、Adam、lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>、15000 步、250 步 warmup。作者强调 gradient clipping 与 <strong>gradient dropping</strong>（梯度范数超阈值直接丢掉整个 batch）是训练稳定的前提。</li><li><strong>推理</strong>：单卡 v6e、81 帧，1.3B 模型 5.92 s（DiT 部分 0.96 s）、15.3 GB 显存；14B 模型 10.03 s（DiT 5.11 s）、42.8 GB。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>三处形式化值得展开。</p><p><strong>为什么取负。</strong> Rectified Flow 把加噪路径设为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mord mathnormal">ϵ</span></span></span></span>，模型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf" style="margin-right:0.016em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 回归速度</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">.</span></span></span></span></span></p><p>推理时若把干净 latent 直接当输入并令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>，网络仍按训练时的约定输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span>。作者取负得到</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ϵ</span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是目标视频 latent。也就是说 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 与目标之间只差一个与内容无关的噪声项，方向上比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 更接近目标；论文的说法是这样「经验上加速收敛、提升性能」。这是个很轻的技巧，但它解释了为什么不需要任何架构改动就能把生成头当感知头用。</p><p><strong>为什么能只用一个损失。</strong> 传统做法是每个任务配一个损失（深度要 scale-invariant loss，分割要 BCE/Dice）。作者把这份复杂度搬到数据侧：先用场景深度中位数归一化消掉尺度歧义，再做非线性压缩</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8019em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8019em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">clip</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mopen">(</span><span class="mord mathnormal">d</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 调节模型在近景细节与远景结构之间的注意力分配。做完这一步，深度就是一张普通的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 图，标准 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 直接够用；任务间的平衡退化为数据配比问题，和 LLM 的做法同构。</p><p><strong>稀疏 token 的时间位置。</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 帧被 VAE 压成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span> 长度，因此 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 个 query token 的帧索引要按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span> 做 position interpolation 才落在预训练 3D RoPE 见过的区间内。作者报告这种「加 query」的方式优于「加额外 attention 层」。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：一个统一架构能不能打专用模型？</strong> 表 1 在六类任务上对比。Ours-Specialist-L（WAN 2.1 14B）法线 Sintel mAE 29.7 / Hi4D 10.99，优于 Lotus-2（30.3）、NormalCrafter（30.7）与 Sapiens（12.14）；深度 Sintel/KITTI/ETH3D/Goliath 分别 0.130 / 0.048 / 0.037 / 0.008；指代分割 Ref-DAVIS 76.4、MeViS 70.0，明显高于 SAM 3（41.3 / 38.3）甚至 SAM 3 + Gemini 3.5 Flash（64.5 / 57.5）；EMDB 上 MPJPE 71.8 优于 TRAM 74.4 与 Genmo 73.0。</p><p>需要如实指出表内并非全胜：ETH3D 深度上 VGGT-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ω</span></span></span></span> 的 0.016 明显优于本文 0.037；相机位姿的 RPE-R 一项 D4RT 拿到 0.126，本文 0.464 差了三倍多；前景分割 VideoMatte 上 RVM 的 0.0010 优于 Specialist 的 0.0027（Generalist 版本才追平到 0.0010）。论文正文只概括为「匹配或超越」，未逐项说明这些落后。</p><p><strong>问题二：增益来自生成目标本身，还是数据/规模？</strong> 表 2 是全文最干净的对照：同一套微调数据（7.5K 视频 / 0.9M 帧）、同一套流程，只换预训练骨干。V-JEPA-H（0.6B）平均 AbsRel 0.281、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0379em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 52.2；VideoMAE V2-H（0.6B）0.175 / 62.0；VideoMAE V2-G（1B）0.154 / 66.9；WAN 2.1-S（1.3B）0.122 / 85.8；WAN 2.1-L（14B）0.093 / 90.7。生成式骨干与判别式自监督骨干之间是数量级差距，而不是几个点。图 9 的补充证据是：随机初始化 DiT 从头训练学习曲线几乎是平的，迁移的预训练层越多性能越好。</p><p><strong>问题三：数据效率。</strong> 同样在表 2，本文用 4 个数据集、8.08K 视频、1.23M 帧，14B 版拿到平均 AbsRel 0.071 / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0379em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 93.8，优于用 22+ 数据集、约 200M 帧训练的 DepthAnything V3-G（0.096 / 89.1）与用约 86M 帧的 D4RT（0.082 / 91.7）；VGGT-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Ω</span></span></span></span>（约 600M 帧）仍以 0.067 / 95.2 领先。摘要的「7× 到 500× 更少数据」由此而来。</p><p><strong>问题四：联合训练的代价。</strong> 作者诚实地报告了负面结果：转成 generalist 后，深度与相机位姿普遍回退或持平，法线在不同 benchmark 上趋势相反，只有前景分割一致受益，指代分割基本不变；3D 关键点被「严重降级」。归因是两条——token 化坐标回归与像素空间预训练目标不同构；从零初始化的额外 token 扰乱了预训练 DiT 的注意力。这条结论比正向结果更有信息量：它反过来支持「最小改动」的设计原则。不过表 1 里 Generalist 行的 EMDB 一栏标为未获得，「严重降级」这一说法在表中没有对应数字。</p><p><strong>涌现行为</strong>：只在单人合成视频上训练的模型，零样本泛化到真实视频、多物体场景，以及动物、拟人角色等分布外类别；作者还观察到输出细节（猫须、发丝软分割）超过 Blender 训练数据本身的质量。这些均为定性证据。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：文生视频生成同时满足时空演化、视觉-语言对齐、可规模化三条，是视觉版的通用预训练目标。GenCeption 把 Rectified Flow 的 DiT 钉在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 做单步前向、对速度取负，直接当特征提取器用。所有稠密任务编码进 3 通道 RGB、稀疏任务交给可学习 token，全靠一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 损失和文本指令区分。同一微调配方下，生成式骨干把 V-JEPA 与 VideoMAE V2 拉开数量级差距，并用少一到两个数量级的数据追平专用几何基座。代价是联合训练会伤害与像素空间不同构的稀疏任务。</p><p><strong>3 句话版</strong>：视频扩散骨干里已经存着几何与语义，重新训练不如把生成流程改成单步前向直接读出来。任务规格从改架构转移到改数据表示，一个损失函数打通稠密与稀疏。控制变量实验显示优势来自生成目标本身，而非数据或规模。</p><p><strong>1 句话版</strong>：把文生视频模型当视觉基座、把感知任务当「换一种颜色约定的视频」，就能用一个架构和一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 损失打赢一堆专用模型。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>所有视觉任务都能被无损地投影进 3 通道 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 的像素空间，从而共享同一个 decoder 和同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 损失。</strong></p><p>这个假设一旦不成立，「统一架构」的卖点就退化成「一堆任务恰好都能画成图」。论文自己的实验就是最强的反证：相机位姿必须靠「Rothko」射线图——把 6 通道拆成中央区放原点、四周放方向——才塞得进 3 通道，这已经是明显的信息挤压，而结果就是 RPE-R 落后 D4RT 三倍多。3D 关键点根本无法画成图，只能加可学习 token，而这恰恰是联合训练中唯一被「严重降级」的任务，作者归因于它「偏离了连续像素空间的预训练」。</p><p>换句话说，统一性在「本来就是图」的任务上成立，在需要结构化输出的任务上是靠打补丁维持的。论文提供的证据是补丁能工作（specialist 模式下 MPJPE 71.8 仍优于 TRAM），缺的证据是补丁能规模化——没有任何实验展示第二个、第三个稀疏任务同时加入后会怎样，而按其自身归因，冲突只会更严重。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且不需要 256 颗 TPU：</p><ul><li><strong>数据</strong>：Sintel + KITTI 的深度子集，各取几百段短片，按论文的中位数归一化与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">clip</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mopen">(</span><span class="mord mathnormal">d</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span></span> 处理。</li><li><strong>模型</strong>：开源 WAN 2.1-1.3B。只训一个 LoRA + 解码路径，冻结大部分骨干以适配单卡。</li><li><strong>实现</strong>：三个变体——(a) 论文配置：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>、输出取负；(b) <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>、输出不取负；(c) 随机采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span>、标准多步蒸馏成单步。</li><li><strong>测量</strong>：验证集 AbsRel 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0379em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 随训练步数的曲线。</li><li><strong>判据</strong>：若 (a) 的收敛速度与终点显著优于 (b)，说明「取负」这一行代码确实在起作用，论文对 Rectified Flow 语义的解释成立；若 (a) 与 (b) 几乎重合，则该设计只是无害的符号约定，真正起作用的是「干净 latent + 单步」。这一条比复现整套多任务系统便宜得多，却直击方法最独特的技术主张。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的替代解释是：<strong>GenCeption 的优势主要来自 WAN 2.1 的规模与数据量，而非「生成」这个目标。</strong> 表 2 的对照虽然控制了微调数据，却没有控制预训练数据——V-JEPA 与 VideoMAE V2 的预训练语料规模、清洗程度、是否带文本，全都和 WAN 2.1 不同。参数量也不齐：V-JEPA-H 0.6B、VideoMAE V2-G 1B 对 WAN 2.1-S 1.3B / L 14B。作者自己写的是「suggestive empirical evidence」，措辞是克制的，但摘要与正文的叙事强度远高于此。</p><p>设计一个能证伪的实验：在<strong>同一份</strong>视频语料（同规模、同清洗、同文本标注）上，用相同参数量的 DiT 分别以三种目标预训练——(i) Rectified Flow 文生视频；(ii) masked video modeling；(iii) 视频-文本对比学习——然后套同一套 GenCeption 后训练。如果 (i) 仍然大幅领先，生成目标假说成立；如果三者接近，那么真正的变量是「大规模带文本的视频语料」，而生成只是当下唯一能吃下这种语料的目标函数——这是一个完全不同（且更朴素）的结论。</p><p>第二个可预测的失败场景：论文全部几何训练数据是合成的（RenderPeople + Blender + TartanAir + Virtual KITTI），而合成渲染的深度/法线本身带系统性偏差（材质简化、无次表面散射、无运动模糊）。在真实的强反射、透明、雨雾场景上，模型很可能同时继承生成先验的「看起来对」和合成真值的系统偏差，产生自信而错误的几何。论文没有任何这类困难域的定量评测。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>局限</strong>：本文把感知统一在「输出空间」上——所有任务被压成 RGB 或 token。但 3 通道是一个纯粹由 VAE 与预训练继承下来的历史约束，射线图那种空间拼贴已经暴露了它的天花板。</p><p><strong>新 framing</strong>：与其把任务塞进像素空间，不如把<strong>预训练目标本身</strong>改成原生多模态视频生成——让基座在预训练阶段就同时生成 RGB、深度、法线、mask 等多个通道流（类似 4M 的多模态 masked modeling，但在视频域、在生成目标下）。这样后训练不需要任何数据格式设计，任务规格退化为「解码哪几路输出」，而稀疏结构化输出可以作为第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 路模态原生参与预训练，从根本上消除本文观察到的「额外 token 破坏注意力」问题。</p><p><strong>可借鉴的相邻领域工具</strong>：多模态 masked modeling（4M/4M-21）的模态 dropout 与 token 化方案；语音领域的多码本残差量化（用于把结构化坐标变成与像素同构的离散流）；以及 mixture-of-transformers 的模态专家路由，用来控制多路输出带来的容量竞争。</p><p><strong>第一个实验</strong>：在一份中等规模的合成视频语料上（可完全控制真值），预训练两个同参数量的 DiT——(A) 只生成 RGB，(B) 生成 RGB+深度+法线三路。然后对两者施加相同的 GenCeption 后训练，比较 (i) 下游任务性能、(ii) 联合训练时任务间的干扰程度（本文报告的最大痛点）、(iii) 数据效率曲线。如果 (B) 显著减轻多任务干扰，就说明「统一」应该发生在预训练侧而不是数据格式侧，本文的数据表示工程只是过渡方案。</p>',58)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
